package zone.moddev.mc.ironagearchitecture.roof;

import java.util.*;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.BlockPos;
import zone.moddev.mc.ironagearchitecture.block.WindowGeometry;

/** Piecewise planar roofs: bounded, explicit design work, with no smoothing surveys. */
public final class RoofDesignPlanner {
    private final RoofPlan p;private final RoofAssembly out;
    final double u0,u1,v0,v1,mid,base,rate;
    private final List<Cut> cuts=new ArrayList<>();
    private static final class Cut {double a,b,c,d;RoofFeature feature;Cut(double a,double b,double c,double d,RoofFeature feature){this.a=a;this.b=b;this.c=c;this.d=d;this.feature=feature;}boolean at(double u,double v){return u>=a&&u<b&&v>=c&&v<d;}}
    private RoofDesignPlanner(RoofPlan p){this.p=p;out=new RoofAssembly(p);u0=(p.alongX?p.minZ:p.minX)-p.wallInset;u1=(p.alongX?p.maxZ:p.maxX)+1+p.wallInset;v0=(p.alongX?p.minX:p.minZ)-p.wallInset;v1=(p.alongX?p.maxX:p.maxZ)+1+p.wallInset;mid=(u0+u1)/2;base=p.floorY+1+p.base*.5+.25;rate=p.mansard==0?RoofPlan.PITCHES[p.pitch]:1;}
    public static RoofPlan solve(RoofPlan p){p.cells.clear();p.error="";try{if(p.width()<4||p.length()<4||p.width()>32||p.length()>32||p.floorY<0||p.floorY>250||p.pitch<0||p.pitch>2||p.base<0||p.base>8||p.wood<0||p.wood>5||p.seat<0||p.seat>2||p.wallInset<0||p.wallInset>1||p.frame<0||p.frame>2||p.clearance<4||p.clearance>12||p.drop<0||p.drop>4||p.edge<0||p.edge>2||p.mansard<0||p.mansard>3)throw new IllegalArgumentException("Choose a 4 to 32 block floor and valid roof settings.");for(int o:p.overhang)if(o<0||o>4)throw new IllegalArgumentException("Overhangs range from zero to two blocks.");for(int i=0;i<2;i++)if(p.gableFill[i]<0||p.gableFill[i]>6||p.gableMaterial[i]<-1||p.gableMaterial[i]>4||p.gableWood[i]<0||p.gableWood[i]>5)throw new IllegalArgumentException("Choose a valid gable material.");if(p.features.size()>64)throw new IllegalArgumentException("Use at most 64 features in one drawing.");new RoofDesignPlanner(p).build();}catch(IllegalArgumentException bad){p.cells.clear();p.error=bad.getMessage();}return p;}
    public static double surface(RoofPlan p,double u){return new RoofDesignPlanner(p).height(u);}
    public static int u(RoofPlan p,BlockPos at){return p.alongX?at.getZ():at.getX();}public static int v(RoofPlan p,BlockPos at){return p.alongX?at.getX():at.getZ();}
    private BlockPos pos(int u,int y,int v){return p.alongX?new BlockPos(v,y,u):new BlockPos(u,y,v);}
    EnumFacing outward(boolean left){return p.alongX?(left?EnumFacing.NORTH:EnumFacing.SOUTH):(left?EnumFacing.WEST:EnumFacing.EAST);}
    double height(double u){boolean left=u<=mid;double wall=left?u0:u1,run=(u1-u0)/2,t=left?u-u0:u1-u;if(t<0){double e=p.overhang[left?0:1]*.5;return base+t*((p.mansard&(left?1:2))!=0?2:rate)-(e>0?p.drop*.25*Math.min(1,-t/e):0);}if((p.mansard&(left?1:2))!=0){double bend=run/3;return base+2*Math.min(t,bend)+.5*Math.max(0,t-bend);}return base+rate*t;}
    private List<Double> breaks(double a,double b){TreeSet<Double> values=new TreeSet<>();values.add(a);values.add(b);for(double x:new double[]{u0,mid,u1,u0+(u1-u0)/6,u1-(u1-u0)/6})if(x>a+1e-8&&x<b-1e-8)values.add(x);return new ArrayList<>(values);}
    private boolean cut(double u,double v){for(Cut c:cuts)if(c.at(u,v))return true;return false;}
    private void build(){
        // Work out feature footprints before emitting the main covering.
        for(RoofFeature f:p.features){RoofFeature.read(f.write());if(f.u<u0||f.u+1>u1||f.v<v0||f.v+f.width>v1)throw new IllegalArgumentException("Keep features within this roof face.");if(f.type==RoofFeature.WINDOW){if(f.width!=1||f.height!=1)throw new IllegalArgumentException("A flush roof window occupies one roof module.");if(f.u<u0||f.u+1>u1||f.v<v0||f.v+1>v1)throw new IllegalArgumentException("Keep roof windows within a roof face.");List<Double> bs=breaks(f.u,f.u+1);if(bs.size()>2)throw new IllegalArgumentException("Move the roof window clear of the ridge or mansard break.");Cut windowCut=new Cut(f.u,f.u+1,f.v,f.v+1,f);for(Cut old:cuts)if(old.a<windowCut.b&&old.b>windowCut.a&&old.c<windowCut.d&&old.d>windowCut.c)throw new IllegalArgumentException("Separate overlapping roof features.");cuts.add(windowCut);}else if(f.type==RoofFeature.GABLE||f.type==RoofFeature.SHED){boolean left=f.u<mid;double front=left?f.u:f.u+1,top=Math.ceil(height(front))+f.lift*.5+f.height+.125;double apex=top+(f.type==RoofFeature.GABLE?f.width*.5:0);double back=front;while(left?back<mid:back>mid){back+=left?.125:-.125;double roof=height(back),cap=f.type==RoofFeature.GABLE?apex:top+.5*Math.abs(back-front);if(roof>=cap-.02)break;}if((left?back>mid-.125:back<mid+.125)||f.v<v0+1||f.v+f.width>v1-1)throw new IllegalArgumentException("This dormer cannot join before the ridge. Lower it, narrow it or choose a taller roof.");double a=left?f.u:Math.floor(back),b=left?Math.ceil(back):f.u+1;Cut next=new Cut(a,b,f.v,f.v+f.width,f);for(Cut old:cuts)if(old.a<next.b&&old.b>next.a&&old.c<next.d&&old.d>next.c)throw new IllegalArgumentException("Separate overlapping roof features.");cuts.add(next);}}
        double a=u0-p.overhang[0]*.5,b=u1+p.overhang[1]*.5,c=v0-p.overhang[2]*.5,d=v1+p.overhang[3]*.5;
        for(int u=(int)Math.floor(a);u<Math.ceil(b);u++)for(int v=(int)Math.floor(c);v<Math.ceil(d);v++){
            Cut feature=null;for(Cut candidate:cuts)if(candidate.at(u+.5,v+.5))feature=candidate;if(feature!=null&&feature.feature.type==RoofFeature.WINDOW)continue;double lo=Math.max(a,u),hi=Math.min(b,u+1),front=Math.max(c,v),back=Math.min(d,v+1);List<Double> bs=breaks(lo,hi);
            if(feature!=null){for(int i=0;i<bs.size()-1;i++){double l=bs.get(i),rr=bs.get(i+1);joined("main:"+u+":"+v,RoofPart.COVER,0,feature.feature,l,rr,front,back,.5,false,false);double centre=(front+back)/2;joined("timber",RoofPart.TIMBER,p.wood,feature.feature,l,rr,Math.max(front,centre-.09375),Math.min(back,centre+.09375),-.1875,false,true);}continue;}for(int i=0;i<bs.size()-1;i++){double l=bs.get(i),r=bs.get(i+1),h=height(l),j=height(r);String col="main:"+u+":"+v;out.slope(col,RoofPart.COVER,0,l,r,front,back,h,j,.5);double centre=(front+back)/2;double tl=p.edge>0?Math.max(l,a+.3125):l,tr=p.edge>0?Math.min(r,b-.3125):r;if(tr>tl)out.slope("timber",RoofPart.TIMBER,p.wood,tl,tr,Math.max(front,centre-.09375),Math.min(back,centre+.09375),height(tl)-.0625,height(tr)-.0625,-.1875);double band=(l+r)/2,bl=Math.max(l,band-.0625),br=Math.min(r,band+.0625);out.slope("timber",RoofPart.TIMBER,p.wood,bl,br,front,back,height(bl),height(br),-.0625);}
        }
        double apex=height(mid);out.box("timber",RoofPart.TIMBER,p.wood,mid-.125,mid+.125,c,d,apex-.375,apex-.125);
        for(double u:new double[]{u0+.125,u1-.125})out.box("timber",RoofPart.TIMBER,p.wood,u-.125,u+.125,v0,v1,base-.25,base);
        int spans=Math.max(1,(int)Math.ceil((v1-v0-1)/4));for(int i=0;i<=spans;i++){double v=v0+.125+(v1-v0-.25)*i/spans,va=v-.125,vb=v+.125;if(i==0&&RoofGables.material(p,0)>=0)va+=.0625;if(i==spans&&RoofGables.material(p,1)>=0)vb-=.0625;double collar=p.frame==1?p.floorY+1+p.clearance*.5:Math.max(base,Math.min(apex-.375,p.floorY+3.25));if(p.frame==1&&collar+.25>apex)throw new IllegalArgumentException("Raise the roof or choose a steeper pitch for the selected attic clearance.");if(p.frame!=2){double left=u0,right=u1;while(left<mid&&height(left)<collar)left+=.03125;while(right>mid&&height(right)<collar)right-=.03125;out.box("timber",RoofPart.TIMBER,p.wood,left,right,va,vb,collar,collar+.1875);}for(double u:new double[]{u0+.125,u1-.125})out.box("timber",RoofPart.TIMBER,p.wood,u-.125,u+.125,va,vb,p.floorY+1,base);}
        if(p.edge>0)for(boolean left:new boolean[]{true,false}){double e=left?a:b,h=height(e);double floor=p.overhang[left?0:1]==0?p.floorY+1:-1000;out.fascia("edge:"+(left?0:1),p.wood,left?e+.1875:e-.3125,left?e+.3125:e-.1875,c,d,Math.max(floor,h-.375),height(left?e+.3125:e-.3125)-.03125,outward(left));if(p.edge==2)out.box("soffit:"+(left?0:1),RoofPart.SOFFIT,p.wood,left?a+.3125:u1,left?u0:b-.3125,c,d,h-.375,h-.3125);}
        gables();
        for(RoofFeature f:p.features)if(f.type==RoofFeature.WINDOW)roofWindow(f);else if(f.type==RoofFeature.GABLE||f.type==RoofFeature.SHED)dormer(f);
        for(RoofFeature f:p.features)if(f.type==RoofFeature.VERTICAL_WINDOW||f.type==RoofFeature.SOLID_PANEL)verticalWindow(f);
        out.finish();
    }
    private void gables(){
        double bottom=p.floorY+1;
        for(int end=0;end<2;end++){
            int material=RoofGables.material(p,end),wood=RoofGables.wood(p,end);if(material<0)continue;
            double front=end==0?v0:v1-1,back=front+1;String id="gable:"+end;
            for(int u=(int)Math.floor(u0);u<Math.ceil(u1);u++){
                List<Double> bs=breaks(Math.max(u0,u),Math.min(u1,u+1));
                for(int i=0;i<bs.size()-1;i++){
                    double a=bs.get(i),b=bs.get(i+1),h=height(a)+.03125,j=height(b)+.03125;
                    out.wall(id+":wall",material,a,b,front+.03125,back-.03125,bottom,bottom,h,j,false);
                    if(material==2||material==3){
                        out.gableTimber(id+":rake",wood,a,b,front,back,Math.max(bottom,h-.21875),Math.max(bottom,j-.21875),h,j);
                        for(double y=bottom;y<Math.max(h,j);y+=2.5)out.gableTimber(id+":rail",wood,a,b,front,back,y,y,Math.min(h,y+.1875),Math.min(j,y+.1875));
                    }
                }
            }
            if(material==2||material==3){int spans=Math.max(1,(int)Math.ceil((u1-u0)/3));for(int i=0;i<=spans;i++){double centre=u0+.09375+(u1-u0-.1875)*i/spans,a=centre-.09375,b=centre+.09375;for(int j=0;j<breaks(a,b).size()-1;j++){List<Double> bs=breaks(a,b);double l=bs.get(j),r=bs.get(j+1);out.gableTimber(id+":post",wood,l,r,front,back,bottom,bottom,height(l)+.03125,height(r)+.03125);}}}
        }
    }
    private double cap(RoofFeature f,double u,double v){boolean left=f.u<mid;double front=left?f.u:f.u+1,top=Math.ceil(height(front))+f.lift*.5+f.height+.125;return f.type==RoofFeature.GABLE?top+Math.min(v-f.v,f.v+f.width-v):top+.5*Math.abs(u-front);}
    private void joined(String id,int kind,int material,RoofFeature feature,double a,double b,double c,double d,double depth,boolean dormer,boolean timber){double vm=feature.v+feature.width*.5;List<Double> vb=new ArrayList<>();vb.add(c);if(feature.type==RoofFeature.GABLE&&vm>c&&vm<d)vb.add(vm);vb.add(d);for(int section=0;section<vb.size()-1;section++){double lo=vb.get(section),hi=vb.get(section+1);List<double[]> polygon=new ArrayList<>();for(double[] xy:new double[][]{{a,lo},{b,lo},{b,hi},{a,hi}})polygon.add(new double[]{xy[0],xy[1],(dormer?cap(feature,xy[0],xy[1]):height(xy[0]))-(timber?.0625:0)});List<double[]> clipped=new ArrayList<>();double[] previous=polygon.get(polygon.size()-1);double before=(height(previous[0])-cap(feature,previous[0],previous[1]))*(dormer?-1:1);for(double[] current:polygon){double after=(height(current[0])-cap(feature,current[0],current[1]))*(dormer?-1:1);if((before>=0)!=(after>=0)){double t=before/(before-after);clipped.add(new double[]{previous[0]+t*(current[0]-previous[0]),previous[1]+t*(current[1]-previous[1]),previous[2]+t*(current[2]-previous[2])});}if(after>=-1e-9)clipped.add(current);previous=current;before=after;}out.surface(id,kind,material,clipped,depth,dormer&&feature.type==RoofFeature.GABLE);}}
    private void verticalWindow(RoofFeature f){RoofFeature parent=null;for(RoofFeature a:p.features)if(a.id==f.parent&&(a.type==RoofFeature.GABLE||a.type==RoofFeature.SHED))parent=a;if(parent==null)throw new IllegalArgumentException("This window needs its dormer wall.");boolean left=parent.u<mid;double front=left?parent.u:parent.u+1,top=Math.ceil(height(front))+parent.lift*.5+parent.height+.125;double max=parent.type==RoofFeature.GABLE?top+Math.min(f.v-parent.v,parent.v+parent.width-f.v-1):top+.5*Math.abs(f.u-front);if(f.y<p.floorY+1||f.y+f.height>max+.001||f.v<parent.v||f.v>=parent.v+parent.width)throw new IllegalArgumentException("Keep the window below the dormer roof and within its wall.");for(int row=0;row<f.height;row++){BlockPos at=pos(f.u,f.y+row,f.v);out.removeWindow(at);if(f.type==RoofFeature.SOLID_PANEL){EnumFacing face=EnumFacing.getHorizontal(f.facing);double a=f.u,b=f.u+1,c=f.v,d=f.v+1;if(face.getAxis()==(p.alongX?EnumFacing.Axis.Z:EnumFacing.Axis.X)){if(face==outward(true))b=a+.125;else a=b-.125;}else{if(face==outward(true).rotateY())d=c+.125;else c=d-.125;}out.box("feature:"+f.id+":panel",RoofPart.WALL,parent.wall,a,b,c,d,f.y+row,f.y+row+1);}else{int joins=(row>0?WindowGeometry.DOWN:0)|(row<f.height-1?WindowGeometry.UP:0);out.window(new RoofWindow("window:"+f.id+":"+row,at,0,0,0,0,0,f.wood*4+f.finish*2+(f.diamond?0:1),joins,EnumFacing.getHorizontal(f.facing),true,false,false,false));}}}
    private void roofWindow(RoofFeature f){boolean left=f.u<mid;double front=left?f.u:f.u+1,h=height(front),slope=Math.abs(height(f.u+1)-height(f.u));int y=(int)Math.floor(h);BlockPos at=pos(f.u,y,f.v);out.window(new RoofWindow("window:"+f.id,at,0,0,0,RoofAssembly.q(h-y),RoofAssembly.q(slope),f.wood*4+f.finish*2+(f.diamond?0:1),0,outward(left),false,false,false,false).rise(f.cover==1?16:4));}
    private void dormer(RoofFeature f){boolean left=f.u<mid;Cut cut=null;for(Cut c:cuts)if(c.c==f.v&&c.d==f.v+f.width&&c.at(f.u+.5,f.v+.5)){cut=c;break;}if(cut==null)return;double front=left?f.u:f.u+1,h0=height(front),sill=Math.ceil(h0)+f.lift*.5;int sillY=(int)Math.floor(sill);double top=sill+f.height+.125,vm=f.v+f.width*.5;String tag="feature:"+f.id;
        for(int u=(int)cut.a;u<cut.b;u++)for(int v=f.v;v<f.v+f.width;v++){
            double aa=u,bb=u+1,cc=v,dd=v+1;joined(tag+":"+u+":"+v,RoofPart.COVER,f.cover,f,aa,bb,cc,dd,.5,true,false);if(f.type==RoofFeature.GABLE)joined("timber:"+f.wood,RoofPart.TIMBER,f.wood,f,u+.40625,u+.59375,cc,dd,-.1875,true,true);else joined("timber:"+f.wood,RoofPart.TIMBER,f.wood,f,aa,bb,v+.4,v+.6,-.1875,true,true);
            for(boolean edge:new boolean[]{false,true})if(v==(edge?f.v+f.width-1:f.v)){double vv=edge?f.v+f.width-.125:f.v;double cap=f.type==RoofFeature.GABLE?top:top+.5*Math.abs(u+.5-front);double bottom=Math.min(height(aa),height(bb));double topA=f.type==RoofFeature.GABLE?top:top+.5*Math.abs(aa-front),topB=f.type==RoofFeature.GABLE?top:top+.5*Math.abs(bb-front);out.wall(tag+":wall",f.wall,aa,bb,vv,vv+.125,height(aa),height(bb),topA,topB,false);}
        }
        // Cap both returns with the same planes used by their covering.
        for(int v=f.v;v<f.v+f.width;v++){List<Double> vs=new ArrayList<>();vs.add((double)v);if(v<vm&&v+1>vm)vs.add(vm);vs.add((double)v+1);for(int j=0;j<vs.size()-1;j++){double va=vs.get(j),vb=vs.get(j+1),capA=f.type==RoofFeature.GABLE?top+Math.min(va-f.v,f.v+f.width-va):top,capB=f.type==RoofFeature.GABLE?top+Math.min(vb-f.v,f.v+f.width-vb):top,aa=left?front:front-.125;
            out.wall(tag+":wall",f.wall,aa,aa+.125,va,vb,h0,h0,capA,capB,true);
            
        }}
        int first=f.width%2==0?f.width/2-1:f.width/2,count=f.width%2==0?2:1;
        for(int col=first;col<first+count;col++)for(int row=0;row<f.height;row++){BlockPos at=pos(f.u,sillY+row,f.v+col);int joins=(row>0?WindowGeometry.DOWN:0)|(row<f.height-1?WindowGeometry.UP:0);out.window(new RoofWindow("window:"+f.id+":"+col+":"+row,at,0,0,0,0,0,f.wood*4+f.finish*2+(f.diamond?0:1),joins,outward(left),true,col>=f.width/2,false,false));}
    }
}
